mapper.select:
SELECT m.*
FROM sys_flow_model m
WHERE m.id = #{id}
  AND m.tenant_id = #{tenantId}
  AND m.del_flag = 0
LIMIT 1

SELECT m.*, c.category_name AS category_name
FROM sys_flow_model m
LEFT JOIN sys_flow_category c ON c.id = m.category

    m.del_flag = 0
    AND m.tenant_id = #{tenantId}

        AND (
            m.model_name LIKE CONCAT('%', #{modelName}, '%')
            OR m.model_key LIKE CONCAT('%', #{modelName}, '%')
        )


        AND (
            m.category = #{category}
            OR EXISTS (
                SELECT 1
                FROM sys_flow_category fc
                JOIN sys_flow_category selected ON selected.id = #{category} OR selected.category_code = #{category}
                WHERE (fc.id = m.category OR fc.category_code = m.category)
                  AND (fc.id = selected.id OR fc.ancestors LIKE CONCAT('%', selected.id, '/%'))
            )
        )


        AND m.status = #{status}


        AND m.create_by = #{createBy}


ORDER BY m.sort_order ASC, m.create_time DESC, m.id ASC

SELECT COUNT(1) AS total, COALESCE(SUM(CASE WHEN m.status = 0 THEN 1 ELSE 0 END), 0) AS designing, COALESCE(SUM(CASE WHEN m.status = 1 THEN 1 ELSE 0 END), 0) AS deployed, COALESCE(SUM(CASE WHEN m.status = 2 THEN 1 ELSE 0 END), 0) AS suspended, COALESCE(SUM(CASE WHEN m.status = 3 THEN 1 ELSE 0 END), 0) AS disabled FROM sys_flow_model m
m.del_flag = 0 AND m.tenant_id = #{tenantId}
AND ( m.model_name LIKE CONCAT('%', #{modelName}, '%') OR m.model_key LIKE CONCAT('%', #{modelName}, '%') )
AND ( m.category = #{category} OR EXISTS ( SELECT 1 FROM sys_flow_category fc JOIN sys_flow_category selected ON selected.id = #{category} OR selected.category_code = #{category} WHERE (fc.id = m.category OR fc.category_code = m.category) AND (fc.id = selected.id OR fc.ancestors LIKE CONCAT('%', selected.id, '/%')) ) )
AND m.create_by = #{createBy}

SELECT COUNT(1)
FROM sys_flow_model m
WHERE m.model_key = #{modelKey}
  AND m.tenant_id = #{tenantId}
  AND m.del_flag = 0

    AND m.id <> #{excludeId}

SELECT m.id, m.tenant_id, m.model_key, m.model_name, m.description, m.category, m.flow_type, m.designer_type, m.form_type, m.form_id, m.form_json, m.bpmn_xml, m.version, m.process_definition_id, m.deployment_id, m.deployment_key, m.notify_type, m.webhook_url, m.todo_detail_url_template, m.allow_multi_return, m.notify_config, m.status, m.importance_level, m.sort_order, m.deploy_time, m.last_update_by, m.create_by, m.create_time, m.update_time, m.del_flag FROM sys_flow_model m WHERE m.tenant_id = #{tenantId} AND m.status = 1 AND m.del_flag = 0
AND m.category = #{category}
ORDER BY m.sort_order ASC, m.create_time DESC, m.id ASC

SELECT m.* FROM sys_flow_model m WHERE m.tenant_id = #{tenantId} AND m.del_flag = 0 AND m.id IN
#{id}
FOR UPDATE
